from __future__ import annotations

#: A residual at or below this is an articulation.
#:
#: **THE GAP IS NOT THREE ORDERS WIDE AND THE CUT IS DELICATE** -- this said it
#: was both, on the strength of ONE mesh against ONE motion file (58 keys),
#: where real joints measured 0.0000 and the nearest rejection 1.39.
#: `c3_import.solve_skeleton` stacks `MOTION_SAMPLES = 10`, and on that
#: population real joints run continuously from 2e-6 up to 0.2489 with the cut
#: among them. `(2, 3)` on body 001 is `pelvis -> spine_2`; its residual
#: crosses this constant BACK AND FORTH as files are stacked (0.278, 0.251,
#: 0.223, 0.191, 0.286, 0.297 for 8..13 files) and is admitted only at 10 and
#: 11. Rejected, the armature comes out with two roots and `bonelabel` renames
#: bone 3 from `spine_2` to `head`; 123 of 125 body-001 chunks carry the pair.
#: Measured gaps at the shipped 10 files: 0.031 / 0.337 / 0.061 / 0.418 for
#: bodies 001-004.
#:
#: So this number is an absolute cut on an RMS whose TERM COUNT is chosen by the
#: caller, and on the pooled path the margin protecting a real joint was 10.9%.
#:
#: **`solve_from_clips` FIXED THAT, AND EVERYTHING ABOVE NOW DESCRIBES
#: `joint_graph` ONLY.** Per-clip voting judges each clip on its own scale, so
#: the term count stops inflating one number; `c3_import.solve_skeleton` no
#: longer calls `joint_graph` at all. On the live pool (19 clips / 504 frames
#: chosen from 438 declared) `(2, 3)` is admitted and body 001's spine comes out
#: correct and single-rooted.
#:
#: **THE MARGINALITY RELOCATED RATHER THAN VANISHED.** That same edge votes
#: `(yes=10, no=9, abstain=0)` at a mean residual of 0.0833, against a rule of
#: `yes >= 1 and yes >= no` -- a ONE-CLIP margin out of 19, where its two
#: neighbours are unanimous 19-0 at 1e-6. One more dissenting clip rejects it,
#: and the failure is not subtle: two roots, and `bonelabel` renames bone 3 to
#: `head` and bone 4 to `neck`. `tests/test_joint_vote_margin.py` gates that
#: margin directly, because a shape-level check on the spine passes on the wrong
#: side of the flip -- an inverted two-root spine is still a spine.
#:
#: The value is left alone deliberately, and `joint_graph` is kept: it is the
#: single-pool primitive `solve_from_clips` is built on. `tools/bonerig.py`
#: called it pooled until backlog item 40 ported it to `solve_from_clips`
#: (2026-09-29); the remaining pooled callers are measurement scripts under
#: `scratchpad/` and `tools/jointthresh_probe.py`, which study the pool. See
#: `docs/bonejoint_threshold_2026-09-26.md` and
#: `C-2026-09-26-claude-bonejoint-threshold-finding`; reproduce with
#: `py -3 tools/jointthresh_probe.py`.
MAX_RESIDUAL = 0.25

#: Minimum relative rotation, in radians-ish (max element deviation of the
#: relative rotation matrix). Below this the pair is rigid and its zero
#: residual means "underdetermined", not "jointed".
#:
#: **IT FIRES CONSTANTLY AND STILL DECIDES NOTHING, WHICH IS NOT THE SAME AS
#: BEING VALIDATED.** An earlier revision of this comment said it had NEVER
#: fired, measured on the pooled `joint_graph` path where it rejected 0 of the
#: residual-passing pairs on all four shared motion sets. That was true of that
#: path and `solve_from_clips` made it false the same day: abstention runs
#: through `probe_moving` and this constant, so on the live pool it fires 50
#: times on shape 0001 and 285 on 0003.
#:
#: Re-measured through the pool the add-on actually selects, disabling it
#: entirely changes NOTHING: 42 -> 42 edges on shape 0001 and 45 -> 45 on 0003,
#: 0 bones reparented either way -- the abstentions are absorbed by the
#: majority. So 0.02 is no better measured than when it never fired; 0.002 or
#: 0.04 would still look identical here. Keep the check, because a rigid pair
#: does pass the residual and nothing else would catch one, and because
#: abstaining is load-bearing in DESIGN (see `solve_from_clips`) even where it
#: is not in OUTCOME on this install -- but do not read either its silence or
#: its noise as evidence about the number.
#:
#: Note also that `relative_motion` measures deviation from FRAME 0 only, which
#: underestimates the true spread by up to 1.98x, so the effective cut is
#: somewhere in 0.02..0.04 depending on where frame 0 falls in the action.
#:
#: **Measure the LIVE path, not a stand-in.** On a "first 10 loose files"
#: reconstruction, disabling this check reparented 10 bones; on the real pool it
#: reparents 0. The reconstruction and the shipped path disagreed on the whole
#: verdict, not on a figure. See `docs/bonejoint_threshold_2026-09-26.md`.
MIN_RELATIVE_MOTION = 0.02

#: How hard the prior pulls, relative to the trace of the normal matrix.
#: Small enough that a CONSTRAINED direction barely moves -- its eigenvalue
#: is orders larger -- and large enough to pin a FREE one, whose eigenvalue
#: is ~0. It only ever decides the axis the motion cannot decide.
PRIOR_WEIGHT = 1e-6


def matrices_by_key(motion):
    """`Motion` -> ``[[ (3x4) per bone ] per key ]``.

    Rows 0..2 of the C3 row-vector matrix are the basis and row 3 is the
    translation, so element ``v[12 + r]`` is the translation's r-th component.
    The convention only has to be CONSISTENT for a residual, but it has to be
    RIGHT for the solved point to land in the mesh's own space -- and it does:
    the 010-011 joint solves to z=-137.3 against a mesh whose raw Z spans
    -178..0 with the arm at about -140.
    """
    bc = int(motion.bone_count)
    out = []
    for k in motion.keys:
        frame = []
        for b in range(bc):
            v = k.matrices[b]
            frame.append(((v[0], v[4], v[8], v[12]),
                          (v[1], v[5], v[9], v[13]),
                          (v[2], v[6], v[10], v[14])))
        out.append(frame)
    return out


def _solve3(A, rhs):
    """3x3 solve, Gaussian elimination with partial pivoting."""
    M = [list(A[r]) + [rhs[r]] for r in range(3)]
    for c in range(3):
        piv = max(range(c, 3), key=lambda r: abs(M[r][c]))
        if abs(M[piv][c]) < 1e-12:
            return None
        M[c], M[piv] = M[piv], M[c]
        for r in range(3):
            if r == c:
                continue
            f = M[r][c] / M[c][c]
            for k in range(c, 4):
                M[r][k] -= f * M[c][k]
    return tuple(M[r][3] / M[r][r] for r in range(3))


def solve_joint(frames, a, b, prior=None):
    """-> ``(residual, point)``; ``(inf, None)`` when the normals are singular.

    Least squares over every frame at once. `residual` is the RMS distance
    between where the two bones put the solved point **over sqrt(3)**: `n`
    below counts one per COMPONENT, three per frame, so dividing by it gives
    the per-component RMS and not the per-frame distance. The factor is exactly
    1.7320508 (measured, not approximated), it is uniform, and no pair's verdict
    turns on it -- but it means `MAX_RESIDUAL = 0.25` is a true RMS distance of
    0.4330 model units, and every figure in this module's docstring is sqrt(3)
    smaller than the distance it is described as. Either divide by the frame
    count and restate the constants or say what the number is; the present
    pairing cannot both be true. See `docs/bonejoint_threshold_2026-09-26.md`.
    """
    ATA = [[0.0] * 3 for _ in range(3)]
    ATb = [0.0] * 3
    for frame in frames:
        Ma, Mb = frame[a], frame[b]
        for r in range(3):
            d = [Ma[r][c] - Mb[r][c] for c in range(3)]
            e = -(Ma[r][3] - Mb[r][3])
            for i in range(3):
                for j in range(3):
                    ATA[i][j] += d[i] * d[j]
                ATb[i] += d[i] * e
    # RANK DEFICIENCY IS NORMAL, NOT AN ERROR. A hinge rotating about one
    # axis constrains only two degrees of freedom -- the joint's coordinate
    # ALONG the hinge axis is genuinely unknowable from that motion, and the
    # normal matrix is singular no matter how many frames are stacked.
    # Refusing here would drop every elbow, knee and finger in the skeleton.
    #
    # BUT THE FREE AXIS STILL HAS TO BE RESOLVED TO SOMETHING, AND ZERO IS
    # THE WRONG ANSWER. Ridging toward the origin takes the SMALLEST solution,
    # which slides the point along the free axis until it is near the world
    # origin -- so the elbow of an arm at z=140 solved to z=-0.3, putting the
    # upper arm's tail and the forearm's head on the floor, and the left knee
    # solved to x=+16.9, on the RIGHT of the body, which crossed the legs.
    # The residual stayed 0.0000 throughout and was right to: moving along
    # the free axis does not separate the two bones at all.
    #
    # `prior` pulls only that free direction, to a point the geometry
    # nominates -- the midpoint of the two bones' own vertex clouds. The
    # constrained directions are perturbed by ~PRIOR_WEIGHT relative, which
    # is nothing, because their eigenvalues dwarf it.
    tr = ATA[0][0] + ATA[1][1] + ATA[2][2]
    if prior is None:
        lam = max(tr, 1.0) * 1e-9
        for i in range(3):
            ATA[i][i] += lam
    else:
        lam = max(tr, 1.0) * PRIOR_WEIGHT
        for i in range(3):
            ATA[i][i] += lam
            ATb[i] += lam * float(prior[i])
    p = _solve3(ATA, ATb)
    if p is None:
        return float("inf"), None
    tot, n = 0.0, 0
    for frame in frames:
        Ma, Mb = frame[a], frame[b]
        for r in range(3):
            va = sum(Ma[r][c] * p[c] for c in range(3)) + Ma[r][3]
            vb = sum(Mb[r][c] * p[c] for c in range(3)) + Mb[r][3]
            tot += (va - vb) ** 2
            n += 1
    return (tot / max(n, 1)) ** 0.5, p


def relative_motion(frames, a, b):
    """How much `b` rotates relative to `a` across the frames.

    THE COMPANION TO THE RESIDUAL. A rigid pair -- two bones welded together
    for the whole action -- also solves to zero, because every point works.
    Without this, such a pair would be read as a joint and attached
    arbitrarily.
    """
    ref, worst = None, 0.0
    for frame in frames:
        Ma, Mb = frame[a], frame[b]
        rel = [[sum(Ma[k][i] * Mb[k][j] for k in range(3)) for j in range(3)]
               for i in range(3)]
        if ref is None:
            ref = rel
            continue
        worst = max(worst, max(abs(rel[i][j] - ref[i][j])
                               for i in range(3) for j in range(3)))
    return worst


def joint_graph(frames, bones, *, max_residual: float = MAX_RESIDUAL,
                min_motion: float = MIN_RELATIVE_MOTION,
                centroids=None) -> dict:
    """``{(lo, hi): (residual, point)}`` for every pair that is ARTICULATED.

    `centroids` is ``{bone: point}`` in the SAME space as the matrices -- the
    mesh's bind space, which is PHY positions with the CHUNK MATRIX ALREADY
    APPLIED, not Blender ones and not raw ones. The midpoint of a pair's two
    centroids becomes the prior that resolves a hinge's free axis. Without it
    a hinge joint slides to the world origin; see `solve_joint`.

    THIS LINE SAID "so raw PHY positions", WHICH IS FALSE WHEREVER THE CHUNK
    MATRIX IS NOT THE IDENTITY -- 159 of 490 skinned player bodies in one
    install, 79 of 127 on body type 2. `Phy_Load` applies that matrix before a
    bone matrix ever sees a vertex, so raw positions are one transform short,
    and a prior in the wrong space is not a weaker prior: on a hinge it is the
    only term deciding the free axis. `c3_import.solve_skeleton` read this
    docstring and passed raw positions, which put all 23 solved joints of
    `c3/mesh/002188495.c3` outside the skin they join. The caller carries the
    measurement.
    """
    bs = sorted({int(b) for b in bones})
    if not frames:
        return {}
    nb = len(frames[0])
    out = {}
    for i, a in enumerate(bs):
        if a >= nb:
            continue
        for b in bs[i + 1:]:
            if b >= nb:
                continue
            prior = None
            if centroids and a in centroids and b in centroids:
                ca, cb = centroids[a], centroids[b]
                prior = tuple((ca[i] + cb[i]) * 0.5 for i in range(3))
            res, p = solve_joint(frames, a, b, prior)
            if p is None or res > max_residual:
                continue
            if relative_motion(frames, a, b) < min_motion:
                continue
            out[(a, b)] = (res, p)
    return out


def tree_from_joints(bones, graph, *, mass=None) -> dict:
    """``{bone: parent_or_None}`` -- a spanning forest of the joint graph.

    Edges are preferred by LOWEST residual: the strongest articulation claim
    wins a tie, not the lowest bone index.

    The root is the bone with the most joints, because that is the torso --
    the chest articulates with the neck and both shoulders while a fingertip
    articulates with one thing. Rooting by skin mass put the head at the top
    on this body, which poses backwards. `mass` only breaks ties.
    """
    bs = sorted({int(b) for b in bones})
    up = {b: b for b in bs}

    def find(x):
        while up[x] != x:
            up[x] = up[up[x]]
            x = up[x]
        return x

    keep = {b: set() for b in bs}
    for (a, b), (res, _p) in sorted(graph.items(), key=lambda kv: (kv[1][0],
                                                                  kv[0])):
        if a not in up or b not in up:
            continue
        ra, rb = find(a), find(b)
        if ra == rb:
            continue
        up[ra] = rb
        keep[a].add(b)
        keep[b].add(a)

    deg = {b: len(keep[b]) for b in bs}
    parent: dict = {}
    seen = set()
    for b in sorted(bs, key=lambda x: (-deg[x],
                                       -(mass or {}).get(x, 0.0), x)):
        if b in seen:
            continue
        parent[b] = None
        queue, seen_here = [b], {b}
        seen.add(b)
        while queue:
            x = queue.pop(0)
            for y in sorted(keep[x]):
                if y in seen_here:
                    continue
                seen_here.add(y)
                seen.add(y)
                parent[y] = x
                queue.append(y)
    for b in bs:
        parent.setdefault(b, None)
    return parent


#: How much of a clip to sample when asking "which pairs does this clip
#: articulate at all". Six frames is enough to separate a rigid pair from a
#: moving one and it is 100x cheaper than the full clip; the number only ever
#: RANKS candidate clips, and the accept/reject decision is made later on
#: every frame of the chosen ones, so a probe that underestimates costs
#: coverage and can never invent a joint.
PROBE_FRAMES = 6


def probe_moving(frames, pairs, *, min_motion: float = MIN_RELATIVE_MOTION,
                 probe: int = PROBE_FRAMES) -> set:
    """Which of `pairs` this ONE clip articulates, from a cheap subsample.

    `pairs` is an iterable of ``(a, b)``. A pair whose bones are outside the
    clip's bone count is silently absent rather than an error: a 26-bone clip
    says nothing about bone 42 and that is not a fault in either.
    """
    if not frames:
        return set()
    n = len(frames)
    step = max(1, n // max(probe, 1))
    sub = frames[::step][:probe]
    if len(sub) < 2:
        sub = frames[:2]
    if len(sub) < 2:
        return set()
    nb = len(sub[0])
    out = set()
    for a, b in pairs:
        if a >= nb or b >= nb:
            continue
        if relative_motion(sub, a, b) >= min_motion:
            out.add((a, b))
    return out


def solve_from_clips(clips, bones, *, max_residual: float = MAX_RESIDUAL,
                     min_motion: float = MIN_RELATIVE_MOTION,
                     centroids=None):
    """-> ``(graph, census)``. ONE VERDICT PER CLIP, then a majority.

    `clips` is ``[frames, ...]`` -- each element what `matrices_by_key` returns
    for one motion file, kept SEPARATE. `graph` is shaped exactly like
    `joint_graph`'s, ``{(lo, hi): (residual, point)}``, so every existing
    consumer (`tree_from_joints`, `bonelabel`) is unchanged. `census` is
    ``{(lo, hi): (yes, no, abstain)}`` for every pair that was looked at.

    WHY NOT JUST CONCATENATE THE FRAMES, WHICH IS WHAT THIS USED TO DO
    -----------------------------------------------------------------
    Because a pooled residual is ONE RMS over every frame against ONE point,
    and the cut it is compared to is ABSOLUTE. Real clips place a joint
    slightly differently -- a rig is animated, not rigid geometry -- so the
    more clips are stacked the larger that single number grows, until a pair
    every clip calls a clean joint falls off the far side of `MAX_RESIDUAL`.

    MEASURED on 5517 body `004137050`, pooling the coverage-ranked clips in
    order. Every one of these pairs is accepted by ALL 28 clips taken singly
    (28 yes, 0 no, 0 abstain); the columns are the pooled residual:

        pair    k=1      k=2      k=4      k=8     k=16     k=28
        4-8    0.0000   0.0027   0.0019   0.2102  0.1570   0.3097  REJECTED
        11-12  0.0000   0.0357   0.1414   0.1368  0.2768   0.4902  REJECTED
        19-20  0.0000   0.0658   0.1011   0.3232  0.2683   0.3115  REJECTED

    Nothing about the skeleton changed between those columns; only how much
    evidence was averaged into one number. The contrast is the control: CCO
    body `001134070` pairs 3-4 and 4-5 sit at 0.0001 at EVERY pool size, so
    this is not "pooling always inflates" -- it is pooling inflating the pairs
    whose position genuinely drifts between clips.

    On that 5517 body pooling 28 clips lost 4-8, 11-12 and 19-20 and took the
    skeleton from 9 roots to 12; the same pool voted per clip gives 3.
    Measured across seven body/install pairs, per-clip voting is never worse
    on root count than the old ten-loose-file pool and is much better twice
    (5517 shape 0003: 5 roots -> 3; shape 0004: 9 -> 3), where pooling
    REGRESSED two of the seven.

    Per-clip voting judges each clip on its own scale, so a pair stays a joint
    for as long as the clips individually say it is one, however many there
    are.

    THE THREE THINGS A CLIP CAN SAY, AND WHY ABSTAINING IS NOT REJECTING
    -------------------------------------------------------------------
    A clip in which the pair is RIGID is not evidence against a joint -- it is
    no evidence at all, because a rigid pair solves to zero for every point
    (see `relative_motion`). That is the whole defect this replaces: body
    0003's ten unarmed actions hold the hand-to-finger pairs 11-12, 11-14 and
    19-22 perfectly rigid, so a solve over only those frames threw the true
    joints away and accepted 10-12, 10-14 and 18-22 instead -- every one at
    residual 0.0000, indistinguishable from a real articulation by residual
    alone. Abstaining lets the clips that DO bend the fingers decide.

    MAJORITY, NOT "ANY CLIP LIKED IT". `yes >= 1 and yes >= no`. With ~20
    clips some clip fits almost any pair by luck: taking any single yes gave
    77 joints on a 39-bone mesh where the majority rule gives 42 and the
    anatomy has ~24. Ties go to the joint, because a pair half the clips fit
    cleanly is likelier articulated than coincidental.

    THE RESIDUAL IS THE MEAN OVER THE ACCEPTING CLIPS; THE POINT IS THE ONE
    THEY AGREE ON. Those are different statistics on purpose and each was
    measured.

    * The POINT cannot be averaged. Two clips put pair 11-12 eight units
      apart, both perfectly; their midpoint is where NEITHER put the joint.
      So the point is always ONE accepting clip's own solution: the one with
      the lowest residual summed over EVERY accepting clip (`_agreed_point`).
    * The point is NOT the clip that fits ITSELF best, and taking it was a
      real defect (PR #200). A clean clip fits its own point to the floor
      wherever that point is, so the lowest own residual picks the stiffest
      clip, and nothing makes that the clip the others agree with. MEASURED
      2026-09-30, shape 3 at `bonerig`'s default 3,000 frames on
      `CCO-snapshot-2026-08-24`; mean residual over the accepting clips (this
      function's units -- sqrt(3) below a distance, see `solve_joint`):

          pair   clips  own-best point  agreed point  moved
          4-16    140      0.0829          0.0000      0.837
          4-5      59      0.0242          0.0000      0.229
          11-12    24      0.0705          0.0000      0.328
          19-20    34      0.4815          0.0000      2.164

      Own-best put the right clavicle 4-16 0.837 from the mirror of 4-8 and
      0.3631 apart in `c3/0003/000/003.c3`; agreed puts it 0.0166 from the
      mirror and 0.0000 apart (the live CCO install gives the same four
      figures). Retargeting the Gangnam donor onto that clip, `c3retarget`'s
      worst rest offset goes from RightShoulder 14.523 deg to RightHand
      13.663, RightShoulder itself to 12.578. Only the points moved: the
      reported residual is untouched by construction, and the accepted set,
      the census and the tree measured identical (19 of 38 points moved).
      The per-clip ACCEPT stays -- it is what hinges the front skirt flap 65
      to 64 (census 184 yes, 0 no, 102 abstain). `tests/test_bonerig.py`
      carries both: the mechanism hermetically
      (`TheJointIsWhereTheClipsAgree`) and the clavicle on the corpus
      (`TheRightClavicleIsTheMirrorOfTheLeft`).
    * The RESIDUAL cannot be the minimum, and taking it was a real defect in
      the first version of this function. `tree_from_joints` picks edges by
      LOWEST residual, so the residual has to keep discriminating -- and the
      minimum over ~17 clips is ~1e-7 for every plausible pair, which
      flattens the ordering into noise. MEASURED on CCO body 001188495, mean
      residual over the accepting clips:

          3-4  4-5  5-6  6-7  5-9  9-10  10-11  11-12  5-15   0.00001-0.00003
          6-9   neck to shoulder.R, 16 of 17 clips accept        0.09232
          6-15  neck to shoulder.L, 15 of 17                     0.09521
          11-13 forearm.R to finger.R, 9 of 17                   0.05629

      Four orders between a chain edge and a junction coincidence, and the
      minimum sees none of it: all twelve read 0.00000. Ranked by the minimum
      the spanning forest took 6-9 and 6-15 over 5-6, which parented the neck
      to a shoulder and dropped this body from 22 labelled bones to 16. Ranked
      by the mean it is 22 again. The coincidences stay IN the graph -- they
      are real articulations in most clips and saying otherwise would be a
      worse lie -- they simply lose every tie to the chain.
    """
    clips = list(clips)
    bs = sorted({int(b) for b in bones})
    pairs = [(a, b) for i, a in enumerate(bs) for b in bs[i + 1:]]
    votes: dict = {}
    total: dict = {}
    yes: dict = {}
    no: dict = {}
    abstain: dict = {}
    for ci, frames in enumerate(clips):
        if not frames:
            continue
        nb = len(frames[0])
        for a, b in pairs:
            if a >= nb or b >= nb:
                continue
            if relative_motion(frames, a, b) < min_motion:
                abstain[(a, b)] = abstain.get((a, b), 0) + 1
                continue
            prior = None
            if centroids and a in centroids and b in centroids:
                ca, cb = centroids[a], centroids[b]
                prior = tuple((ca[i] + cb[i]) * 0.5 for i in range(3))
            res, p = solve_joint(frames, a, b, prior)
            if p is not None and res <= max_residual:
                yes[(a, b)] = yes.get((a, b), 0) + 1
                total[(a, b)] = total.get((a, b), 0.0) + res
                votes.setdefault((a, b), []).append((ci, p))
            else:
                no[(a, b)] = no.get((a, b), 0) + 1
    graph = {}
    census = {}
    for q in pairs:
        y, n, ab = yes.get(q, 0), no.get(q, 0), abstain.get(q, 0)
        if not (y or n or ab):
            continue
        census[q] = (y, n, ab)
        if y and y >= n:
            # Mean residual for the RANKING, the point the accepting clips
            # agree on for the PLACEMENT -- see the docstring; they are not
            # interchangeable, using the minimum for the ranking cost this
            # body six labelled bones, and using it for the placement moved
            # the right clavicle 0.84 off its mirror.
            graph[q] = (total[q] / y, _agreed_point(clips, votes[q], *q))
    return graph, census


def _residual_form(frames, a, b, o):
    """ONE clip's residual at ANY point, as a quadratic about `o`.

    -> ``(A, g, c, n)`` such that the sum of squared component separations at
    ``o + d`` is ``d.A.d + 2 g.d + c`` over `n` components, so `solve_joint`'s
    residual there is ``sqrt(that / n)``. It is exact -- the separation is
    linear in the point -- and it is accumulated from the separation AT `o`,
    which is small near a joint, so nothing large is subtracted from anything
    large on the way. MEASURED on a hinge 143 units from the origin: this
    form reads 3.2e-16 where `solve_joint` reads 3.5e-16, and the textbook
    ``p.A.p - 2 p.b + c`` reads 4.0e-8 (its raw sum went negative); over
    shape 3's pair 4-8 the two err by 1e-14 and 3e-8. Small beside the
    figures `_agreed_point` separates, but this form costs nothing more.
    """
    A = [[0.0] * 3 for _ in range(3)]
    g = [0.0] * 3
    c, n = 0.0, 0
    for frame in frames:
        Ma, Mb = frame[a], frame[b]
        for r in range(3):
            d = [Ma[r][k] - Mb[r][k] for k in range(3)]
            s = sum(d[k] * o[k] for k in range(3)) + (Ma[r][3] - Mb[r][3])
            for i in range(3):
                for j in range(3):
                    A[i][j] += d[i] * d[j]
                g[i] += d[i] * s
            c += s * s
            n += 1
    return A, g, c, n


def _form_residual(form, o, p) -> float:
    """`solve_joint`'s residual at `p`, from a `_residual_form` about `o`."""
    A, g, c, n = form
    d0, d1, d2 = p[0] - o[0], p[1] - o[1], p[2] - o[2]
    q = (c + 2.0 * (g[0] * d0 + g[1] * d1 + g[2] * d2)
         + d0 * (A[0][0] * d0 + A[0][1] * d1 + A[0][2] * d2)
         + d1 * (A[1][0] * d0 + A[1][1] * d1 + A[1][2] * d2)
         + d2 * (A[2][0] * d0 + A[2][1] * d1 + A[2][2] * d2))
    return (max(q, 0.0) / max(n, 1)) ** 0.5


def _agreed_point(clips, votes, a, b):
    """Of the accepting clips' own points, the one ALL of them fit best.

    `votes` is ``[(clip index, point), ...]`` in clip order. Each candidate
    is scored by its residual in every accepting clip -- its own included --
    and the lowest total wins; an exact tie keeps the earlier clip. Two clips
    that fit EQUALLY well almost never tie exactly, and rounding picks
    between them: `tests/test_motionpool.py` `Disagreement` is one motion
    about two pivots, scoring 5.7e-9 apart. Either answer is right there.
    Still ONE clip's solution, never a blend: see `solve_from_clips` for why
    the point cannot be averaged and why the clip that fits ITSELF best is
    not it.
    """
    if len(votes) == 1:
        return votes[0][1]
    forms = [(_residual_form(clips[ci], a, b, p), p) for ci, p in votes]
    chosen, low = None, None
    for _ci, cand in votes:
        score = sum(_form_residual(f, o, cand) for f, o in forms)
        if low is None or score < low:
            chosen, low = cand, score
    return chosen


def unresolved_pairs(census) -> list:
    """Pairs no clip could speak to at all -- RIGID in every single one.

    These are NOT non-joints and must not be reported as though the solve had
    decided anything about them. Body 0003's own idle holds all 300 pairs of
    its 25 skinned bones below the motion floor, so an idle-only pool abstains
    on everything; saying "no joints here" would be a measurement of the clip
    and not of the skeleton. `docs/motion_policy_2026-09-21.md` section 2 has
    the other reading -- 30 of body 0003's bones are WELDED to a host and will
    abstain in every clip ever authored, correctly and permanently.
    """
    return sorted(q for q, (y, n, ab) in census.items() if ab and not y and not n)
